package org.eclipse.jdt.internal.ui.viewsupport;

// Simulate JDT Core IMethod and JavaModelException for example compilation
package org.eclipse.jdt.core {
    public interface IMethod {
        boolean isConstructor();
        boolean exists();
    }
    public class JavaModelException extends Exception {
        private static final long serialVersionUID = 1L;
    }
}

// Original context class
import org.eclipse.jdt.core.IMethod;
import org.eclipse.jdt.core.JavaModelException;

class JavaElementLabels {
    public static final int T_TYPE_PARAMETERS = 1;
    public static boolean getFlag(int flags, int flag) {
        return (flags & flag) != 0;
    }
}

public class MyClass {
    public void someMethod(int flags, IMethod method) throws JavaModelException {
        if (JavaElementLabels.getFlag(flags, JavaElementLabels.T_TYPE_PARAMETERS) && method.isConstructor()) {
            System.out.println("Processing...");
        }
    }
}

